const apiTokenPrefix = "ent_"

var githubHTTPClient = &http.Client{Timeout: 10 * time.Second}

// AuthResult holds the resolved user ID from authentication.
type AuthResult struct {
	UserID    string
	Login     string
	AccountID string // Verified JWT sub, forwarded to whichever repo resolver is configured; empty for token/PAT paths.
	Token     string // Raw verified core JWT; never populated for API token or GitHub token paths.
	Issuer    string // Verified JWT iss (one of the trusted issuers); empty for token/PAT paths.
}

// resolveUserID extracts and validates user identity from the request.
// Auth chain: Entire API token (ent_*) → Core JWT → GitHub token fallback.
func resolveUserID(ctx context.Context, r *http.Request, dbClient *db.Client, jwksVerifier *JWKSVerifier) (*AuthResult, error) {
	authHeader := r.Header.Get("Authorization")
	if authHeader == "" {
		return nil, fmt.Errorf("missing Authorization header")
	}

	// Strip "Bearer " or "token " prefix.
	token := authHeader
	for _, prefix := range []string{"Bearer ", "bearer ", "token ", "Token "} {
		if strings.HasPrefix(token, prefix) {
			token = strings.TrimPrefix(token, prefix)
			break
		}
	}
	if token == "" {
		return nil, fmt.Errorf("empty token in Authorization header")
	}

	// Try Entire API token (ent_*).
	if strings.HasPrefix(token, apiTokenPrefix) {
		hash := sha256Hex(token)
		lookup, err := dbClient.GetAPITokenByHash(ctx, hash)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return nil, fmt.Errorf("invalid or expired token")
			}
			return nil, fmt.Errorf("looking up API token: %w", err)
		}

		expiresAt, err := time.Parse("2006-01-02 15:04:05", lookup.ExpiresAt)
		if err != nil {
			expiresAt, err = time.Parse(time.RFC3339, lookup.ExpiresAt)
			if err != nil {
				return nil, fmt.Errorf("parsing token expiry: %w", err)
			}
		}
		if time.Now().After(expiresAt) {
			return nil, fmt.Errorf("token expired")
		}

		return &AuthResult{UserID: lookup.UserID}, nil
	}

	// Try entire-core JWT (3-segment token that isn't ent_*).
	if jwksVerifier != nil && looksLikeJWT(token) {
		claims, err := jwksVerifier.Verify(ctx, token)
		if err == nil {
			githubID, parseErr := strconv.ParseInt(claims.ProviderUserID, 10, 64)
			if parseErr != nil {
				return nil, fmt.Errorf("invalid provider_user_id in JWT: %w", parseErr)
			}
			userID, dbErr := dbClient.GetUserByGithubID(ctx, githubID)
			if dbErr != nil {
				if errors.Is(dbErr, sql.ErrNoRows) {
					return nil, fmt.Errorf("user not found in Entire")
				}
				return nil, fmt.Errorf("looking up user: %w", dbErr)
			}
			return &AuthResult{
				UserID:    userID,
				Login:     claims.Handle,
				AccountID: accountIDFromSubject(claims.Subject),
				Token:     token,
				Issuer:    claims.Issuer,
			}, nil
		}
		// JWT-shaped token failed validation — don't waste a GitHub API call.
		return nil, fmt.Errorf("invalid or expired token")
	}

	// Fallback: GitHub token.
	ghUser, err := getGitHubUser(ctx, token)
	if err != nil {
		return nil, fmt.Errorf("GitHub auth failed: %w", err)
	}

	userID, err := dbClient.GetUserByGithubID(ctx, ghUser.ID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, fmt.Errorf("user not found in Entire")
		}
		return nil, fmt.Errorf("looking up user: %w", err)
	}

	return &AuthResult{UserID: userID, Login: ghUser.Login}, nil
}

