// GetUserByGithubID looks up an Entire user by their GitHub user ID.
func (c *Client) GetUserByGithubID(ctx context.Context, githubID int64) (string, error) {
	var userID string
	err := c.db.QueryRowContext(ctx,
		`SELECT id FROM users WHERE github_id = ?`,
		githubID,
	).Scan(&userID)
	if err != nil {
		return "", err
	}
	return userID, nil
}

