// Kysely database helpers - User functions

import type { Kysely, Updateable } from "kysely"

import type { DB, Users } from "../../../db/types"
import type { User, CachedUser } from "../../types"
import type { UsersNamespace } from "../db/db-types"
import { getCachedUser, setCachedUser } from "../kv"
import { assertValidUuid, generateId } from "../uuid"

// --- Row Conversion ---

/** Convert a Kysely users row to the User type (number→boolean, Date→string). */
function rowToUser(row: {
  id: string
  github_id: number
  github_login: string | null
  github_token_enc: string | null
  github_refresh_token_enc: string | null
  github_token_expires_at: Date | null
  is_admin: number
  created_at: Date
  repos_synced_at: Date | null
  last_visited_at: Date | null
}): User {
  return {
    id: row.id,
    github_id: row.github_id,
    github_login: row.github_login,
    github_token_enc: row.github_token_enc,
    github_refresh_token_enc: row.github_refresh_token_enc,
    github_token_expires_at: row.github_token_expires_at?.toISOString() ?? null,
    created_at: row.created_at.toISOString(),
    repos_synced_at: row.repos_synced_at?.toISOString() ?? null,
    last_visited_at: row.last_visited_at?.toISOString() ?? null,
  }
}

// --- User Functions ---

export async function findUserByGitHubId(db: Kysely<DB>, githubId: number): Promise<User | null> {
  const row = await db
    .selectFrom("users")
    .selectAll()
    .where("github_id", "=", githubId)
    .executeTakeFirst()

  return row ? rowToUser(row) : null
}

export async function findUserById(db: Kysely<DB>, id: string): Promise<User | null> {
  assertValidUuid(id, "userId")
  const row = await db.selectFrom("users").selectAll().where("id", "=", id).executeTakeFirst()

  return row ? rowToUser(row) : null
}

export async function createUser(
  db: Kysely<DB>,
  data: {
    github_id: number
    github_login: string
    github_token_enc: string | null
    github_refresh_token_enc?: string | null
    github_token_expires_at?: string | null
  },
): Promise<User> {
  const id = generateId()

  await db
    .insertInto("users")
    .values({
      id,
      github_id: data.github_id,
      github_login: data.github_login,
      github_token_enc: data.github_token_enc,
      github_refresh_token_enc: data.github_refresh_token_enc ?? null,
      github_token_expires_at: data.github_token_expires_at
        ? new Date(data.github_token_expires_at)
        : null,
      last_visited_at: null,
      repos_synced_at: null,
    })
    .execute()

  // MySQL doesn't support RETURNING, so fetch the inserted row
  const row = await db
    .selectFrom("users")
    .selectAll()
    .where("id", "=", id)
    .executeTakeFirstOrThrow()

  return rowToUser(row)
}

