import { getCookie } from "hono/cookie"

import type { Env } from "../../env"
import { bearerTokenFromAuthorization } from "../authorization-header"
import { coreFetchTimeoutMs } from "../entire-core/config"
import { getValidLoginJwt } from "../entire-core/core-login"
import { coreTrustedIssuers } from "../entire-core/trusted-issuer"

/** Resolve a bearer token for entire-api SpiceDB authz.
 *
 * Session-cookie callers (browser): the login JWT IS the account access token
 * (COR-1095, self-audience, scope=entire:session) — forwarded directly, no
 * exchange. Bearer callers (CLI): assumed to already carry a token entire-api
 * accepts (see proxy.ts's isAccountAccessTokenJwt for the dual-shape handling
 * the repo-scoped bearer path needs; this fan-out has never distinguished the
 * two shapes, since it has always forwarded the bearer as-is).
 *
 * Shared by code-search (peregrine) and semantic search (entire-search) — both
 * proxy through the entire-api gateway.
 *
 * `opts.loginJwt` lets a caller that already resolved the session's login JWT
 * reuse it, avoiding a duplicate `getValidLoginJwt` round-trip when the same
 * request also needs the login JWT for something else (e.g. slug → ULID
 * resolution). Ignored on the bearer/CLI path. */
export async function resolveSearchBearerToken(
  c: {
    req: { header: (name: string) => string | undefined }
    env: Env
  },
  opts?: { loginJwt?: string },
): Promise<string | undefined> {
  // CLI path: bearer token is forwarded as-is.
  const bearerToken = bearerTokenFromAuthorization(c.req.header("Authorization"))
  if (bearerToken) return bearerToken

  // Browser path: the session's login JWT IS the account access token.
  const sessionToken = getCookie(c as any, "session")
  if (
    !sessionToken ||
    !c.env.ENCRYPTION_KEY ||
    !c.env.ENTIRE_CORE_BASE_URL ||
    !c.env.ENTIRE_CORE_CLIENT_ID ||
    !c.env.ENTIRE_CORE_CLIENT_SECRET
  ) {
    return undefined
  }

  // Reuse a pre-resolved login JWT when the caller supplied one; otherwise
  // resolve it here from the session token. Login JWT refresh defaults to the
  // configured core (ENTIRE_CORE_BASE_URL) but routes to the login JWT's
  // issuing cell when its `iss` is an allowlisted trusted issuer —
  // trustedIssuers carries that allowlist into getValidLoginJwt (COR-932).
  if (opts?.loginJwt) return opts.loginJwt

  const homeCfg = {
    coreBaseUrl: c.env.ENTIRE_CORE_BASE_URL,
    clientId: c.env.ENTIRE_CORE_CLIENT_ID,
    clientSecret: c.env.ENTIRE_CORE_CLIENT_SECRET,
    trustedIssuers: coreTrustedIssuers(c.env),
    fetchTimeoutMs: coreFetchTimeoutMs(c.env),
  }
  const loginJwtResult = await getValidLoginJwt(
    { kv: c.env.ENTIRE_CACHE, secret: c.env.ENCRYPTION_KEY, cfg: homeCfg },
    sessionToken,
  )
  return loginJwtResult.kind === "jwt" ? loginJwtResult.jwt : undefined
}

