authOAuthRoutes.get("/core/resolve-callback", async (c) => {
  const config = getCoreAuthConfig(c.env)
  if (!config) return c.text("entire-core auth not configured", 503)
  const fallback = (next?: string) =>
    redirectToCoreAuthorize(c, { baseUrl: config.baseUrl, clientId: config.clientId, next })

  const state = c.req.query("state")
  const jurisdiction = c.req.query("jurisdiction")
  if (!state || !jurisdiction) {
    console.warn("Core resolve callback: missing state/jurisdiction; falling back")
    return fallback()
  }
  const stored = await c.env.ENTIRE_CACHE.get(`core_juri_state:${state}`)
  if (!stored) {
    console.warn("Core resolve callback: invalid or expired state; falling back")
    return fallback()
  }
  await c.env.ENTIRE_CACHE.delete(`core_juri_state:${state}`)
  const juri = parseCoreJuriStateContext(stored)
  const ua = c.req.header("user-agent") || "unknown"
  if (!juri || juri.ua !== ua) {
    console.warn("Core resolve callback: state/user-agent mismatch; falling back")
    return fallback(juri?.next)
  }
  // Covers both a structurally invalid jurisdiction and a valid-but-untrusted
  // one (region routing gated on the same ENTIRE_CORE_TRUSTED_ISSUERS
  // allowlist /auth/core/callback enforces before redeeming a code) — either
  // way, routing there would only dead-end at login_failed.
  const regionBaseUrl = resolveTrustedRegionBaseUrl(c.env, config, jurisdiction)
  if (!regionBaseUrl) {
    console.warn("Core resolve callback: invalid or untrusted jurisdiction; falling back")
    return fallback(juri.next)
  }
  return redirectToCoreAuthorize(c, {
    baseUrl: regionBaseUrl,
    clientId: config.clientId,
    next: juri.next,
  })
})

