// TestProbeCell_Classification pins the readiness reading of each status
// query-serve can answer a q-less GET with. The route authenticates before it
// parses, so the 400 "q is required" is the proof that the credential cleared
// — no search is run. 401/403 is the entireio/cli#2121 case: the credential
// was refused by this service specifically, which must never be reported as a
// missing route (opposite remedies).
func TestProbeCell_Classification(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name   string
		status int
		body   string
		want   Availability
	}{
		{name: "400 q required means auth cleared", status: http.StatusBadRequest, body: `{"error":"Query parameter 'q' is required"}`, want: AvailabilityOK},
		{name: "200 is available", status: http.StatusOK, body: `{"results":[]}`, want: AvailabilityOK},
		{name: "401 is a rejected credential", status: http.StatusUnauthorized, body: `{"error":"Unauthorized"}`, want: AvailabilityCredentialsRejected},
		{name: "403 is a rejected credential", status: http.StatusForbidden, body: `{"error":"Forbidden"}`, want: AvailabilityCredentialsRejected},
		{name: "plain 404 is an undeployed route", status: http.StatusNotFound, body: "404 page not found", want: AvailabilityRegionUnavailable},
		{name: "json 404 without a filter is still undeployed", status: http.StatusNotFound, body: `{"error":"not found"}`, want: AvailabilityRegionUnavailable},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path != v4ServicePath {
					t.Errorf("path = %q, want %q", r.URL.Path, v4ServicePath)
				}
				if r.URL.Query().Has("q") {
					t.Error("probe must not send q: it must never run a real search")
				}
				w.WriteHeader(tc.status)
				w.Write([]byte(tc.body)) //nolint:errcheck // test helper response
			}))
			defer srv.Close()

			got, err := ProbeCell(context.Background(), api.NewClientWithBaseURL("tok", srv.URL))
			if err != nil {
				t.Fatalf("ProbeCell: %v", err)
			}
			if got != tc.want {
				t.Errorf("availability = %q, want %q", got, tc.want)
			}
		})
	}
}

// TestProbeCell_ServerErrorIsAnError: a 5xx is neither a verdict about the
// credential nor about the route; it must surface as an error carrying the
// status and the service's message so doctor can print it as "unreachable".
func TestProbeCell_ServerErrorIsAnError(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
		w.Write([]byte(`{"error":"Search failed"}`)) //nolint:errcheck // test helper response
	}))
	defer srv.Close()

	got, err := ProbeCell(context.Background(), api.NewClientWithBaseURL("tok", srv.URL))
	if err == nil {
		t.Fatalf("expected an error for a 500, got availability %q", got)
	}
	if !strings.Contains(err.Error(), "500") || !strings.Contains(err.Error(), "Search failed") {
		t.Errorf("error = %q, want it to carry the status and the service message", err)
	}
}

