package search

import (
	"context"
	"fmt"
	"io"
	"net/http"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

// Availability is a cell's semantic-search readiness for the caller, as a
// stable machine-readable code. It is the vocabulary `entire doctor` reports
// in and the one a structured `entire search --json` error should reuse
// (ENCLI-302): the three outcomes demand different things of the user —
// nothing, waiting for a rollout, or filing a report — so they must never be
// folded into one another.
type Availability string

const (
	// AvailabilityOK: the cell exposes the route and accepted the caller's
	// credential.
	AvailabilityOK Availability = "available"
	// AvailabilityRegionUnavailable: the cell's gateway has no semantic-search
	// route — query-serve is not deployed in this region yet. Ages out with a
	// rollout; `entire search` reports it as "not yet available in the
	// region(s) hosting this search".
	AvailabilityRegionUnavailable Availability = "region_unavailable"
	// AvailabilityCredentialsRejected: the route exists and refused the
	// caller's bearer (401/403). Cell clients carry the login JWT — the same
	// bearer code search accepts at the same host — so this is the
	// semantic-search service declining an account, not a session the user
	// can refresh, and it does not age out (entireio/cli#2121).
	AvailabilityCredentialsRejected Availability = "credentials_rejected"
)

// ProbeCell asks one entire-api cell whether it can serve semantic search for
// the caller, without running a search: a q-less GET of the v4 route.
// Query-serve authenticates before it parses the query, so its 400 "Query
// parameter 'q' is required" is the proof that the credential cleared —
// cheaper than a real search (no embedding, no rerank) and independent of
// what is indexed.
//
// A 404 is read the way CellV4 reads an unfiltered one: no repo filter was
// sent, so there is no repo to blame and the route itself is absent. Any
// other non-2xx (5xx, unexpected 4xx) is returned as an error — it is neither
// a verdict about the credential nor about the route.
func ProbeCell(ctx context.Context, client *api.Client) (Availability, error) {
	resp, err := client.Get(ctx, v4ServicePath)
	if err != nil {
		return "", fmt.Errorf("calling search service: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}
	switch resp.StatusCode {
	case http.StatusOK, http.StatusBadRequest:
		return AvailabilityOK, nil
	case http.StatusUnauthorized, http.StatusForbidden:
		return AvailabilityCredentialsRejected, nil
	case http.StatusNotFound:
		return AvailabilityRegionUnavailable, nil
	}
	_, err = parseSearchResponse(resp.StatusCode, body)
	return "", err
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/internal/coreapi"
	"github.com/spf13/cobra"
)

// semanticSearchProbeTimeout bounds each cell probe. Shorter than the search
// path's per-cell budget: a probe runs no search, and doctor is interactive.
const semanticSearchProbeTimeout = 10 * time.Second

// checkSemanticSearch reports whether `entire search` can work from this
// account: it probes every cell a search would fan out to and classifies each
// as available, region-unavailable, or credentials-rejected. Read-only,
// warn-only, and silent when not logged in — doctor also serves people who
// never use the hosted side.
//
// It exists because the failure it catches is otherwise invisible until the
// user searches: enable, capture and push all succeed for an account whose
// login the semantic-search service refuses, and the search then fails with a
// 401 that looks like a login problem and isn't (entireio/cli#2121).
func checkSemanticSearch(cmd *cobra.Command) {
	results, err := probeSemanticSearchCells(cmd.Context(), false)
	renderSemanticSearchCheck(cmd.OutOrStdout(), results, err)
}

// probeSemanticSearchCells resolves the cells `entire search` would query for
// this account — one per hosting cell of the caller's repo index, or the home
// cell when the index is empty — and probes each. Mirrors the unfiltered
// branch of semanticSearchV4Session.search so doctor and search agree on
// which cells matter; a control-plane failure is returned, not guessed around.
func probeSemanticSearchCells(ctx context.Context, insecureHTTP bool) ([]cellCallResult[search.Availability], error) {
	coreClient, err := newCellCoreClient()
	if err != nil {
		return nil, err
	}
	indexCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
	defer cancel()
	index, err := coreClient.ListRepos(indexCtx, coreapi.ListReposParams{})
	if err != nil {
		return nil, fmt.Errorf("listing repos for cell discovery: %w", err)
	}
	cells, _ := groupReposByCell(index.Repos)
	if len(cells) == 0 {
		// Nothing mirrored yet — the home cell is still worth asking, so an
		// account learns its search status before it has repos to search.
		cells = []cellGroup{{}}
	}
	resolveCellBaseURLs(ctx, coreClient, cells)
	return fanOutCells(ctx, insecureHTTP, semanticSearchProbeTimeout, cells,
		func(ctx context.Context, _ cellGroup, client *api.Client) (search.Availability, error) {
			return search.ProbeCell(ctx, client)
		})
}

// renderSemanticSearchCheck prints the doctor report for the probe outcomes.
// Each non-OK class gets its own block because each asks something different
// of the user; a healthy cell alongside a failing one is mentioned so the
// report doesn't read as "search is broken everywhere".
func renderSemanticSearchCheck(w io.Writer, results []cellCallResult[search.Availability], err error) {
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return
		}
		fmt.Fprintln(w, "Semantic search: NOT CHECKED")
		fmt.Fprintf(w, "  %v\n", err)
		return
	}
	if len(results) == 0 {
		return
	}

	var ok, unavailable, rejected, unreachable []string
	var unreachableErrs []string
	for _, r := range results {
		label := r.group.label()
		switch {
		case r.err == nil && r.value == search.AvailabilityOK:
			ok = append(ok, label)
		case r.err == nil && r.value == search.AvailabilityCredentialsRejected:
			rejected = append(rejected, label)
		case r.err == nil && r.value == search.AvailabilityRegionUnavailable,
			errors.Is(r.err, auth.ErrNoCellForJurisdiction):
			unavailable = append(unavailable, label)
		default:
			unreachable = append(unreachable, label)
			unreachableErrs = append(unreachableErrs, fmt.Sprintf("%s: %v", label, r.err))
		}
	}

	if len(rejected) == 0 && len(unavailable) == 0 && len(unreachable) == 0 {
		fmt.Fprintf(w, "✓ Semantic search: OK (%s)\n", strings.Join(ok, ", "))
		return
	}

	if len(rejected) > 0 {
		fmt.Fprintf(w, "Semantic search: CREDENTIALS REJECTED in %s\n", strings.Join(rejected, ", "))
		fmt.Fprintln(w, "  The semantic-search service refused the login that every other Entire")
		fmt.Fprintln(w, "  service accepts, so `entire search` fails there with a 401 while")
		fmt.Fprintln(w, "  `entire search --code` works. This is not fixed by logging in again:")
		fmt.Fprintln(w, "  the service could not match your account, which is a server-side")
		fmt.Fprintln(w, "  provisioning problem. Run `entire doctor bundle` and attach it to a")
		fmt.Fprintln(w, "  bug report.")
	}
	if len(unavailable) > 0 {
		fmt.Fprintf(w, "Semantic search: NOT AVAILABLE in %s\n", strings.Join(unavailable, ", "))
		fmt.Fprintln(w, "  Semantic search is not yet deployed in the region(s) hosting these repos;")
		fmt.Fprintln(w, "  `entire search` reports them as \"not yet available in the region(s)")
		fmt.Fprintln(w, "  hosting this search\". Code search (`entire search --code`) is unaffected.")
	}
	if len(unreachable) > 0 {
		fmt.Fprintf(w, "Semantic search: UNREACHABLE in %s\n", strings.Join(unreachable, ", "))
		for _, e := range unreachableErrs {
			fmt.Fprintf(w, "  %s\n", e)
		}
	}
	if len(ok) > 0 {
		fmt.Fprintf(w, "  Semantic search is working in %s.\n", strings.Join(ok, ", "))
	}
	logging.Debug(context.Background(), "doctor: semantic search probe",
		"ok", ok, "credentials_rejected", rejected, "region_unavailable", unavailable, "unreachable", unreachable)
}

