// claims on success. jwtverify.TrustedIssuers handles issuer trust, JWKS
// fetch/cache/refresh, signature verification, RFC 7519 time claims
// (including requiring exp to be present), and audience matching (any-of,
// ENT-1050) — including enforcing HTTPS-only JWKS origins and safe
// redirects. entire-search only additionally requires the caller be a
// GitHub-identified account.
func (v *JWKSVerifier) Verify(ctx context.Context, tokenString string) (*CoreClaims, error) {
	claims := &CoreClaims{}
	if err := v.trustedIssuers.Verify(ctx, tokenString, claims); err != nil {
		return nil, fmt.Errorf("verifying token: %w", err)
	}

	if claims.Provider != "github" {
		return nil, fmt.Errorf("unsupported provider: %q", claims.Provider)
	}
	if claims.ProviderUserID == "" {
		return nil, fmt.Errorf("missing provider_user_id")
	}

	return claims, nil
}
