func (a *Authenticator) verifyBearer(ctx context.Context, raw string) (*Identity, error) {
	verifier, issuer, err := a.verifierFor(raw)
	if err != nil {
		return nil, err
	}
	// The shared verifier checks the signature (EdDSA/RS256/ES256) against
	// Core's JWKS, requires exp, and validates the nbf/iat claims that are
	// present. Audience/scope shape classification happens below, since this
	// Authenticator dual-accepts two shapes.
	var claims bearerClaims
	if err := verifier.Verify(ctx, raw, &claims); err != nil {
		return nil, fmt.Errorf("auth: invalid bearer: %w", err)
	}
	// Pin the issuer when one is configured. Without this, cross-issuer
	// acceptance is only foreclosed by the JWKS being bound to a single issuer;
	// an exact iss match makes that guarantee explicit at the token layer.
	// Under trustedIssuers dispatch the pin is the issuer the token was routed
	// to, so this also re-checks the verified `iss` against the unverified one
	// that chose the key set.
	if issuer != "" && claims.Issuer != issuer {
		return nil, fmt.Errorf("auth: unexpected issuer %q", claims.Issuer)
	}

	// Jurisdiction token (ADR 20260612): aud is the configured jurisdiction
	// host exactly, plus scope=openid.
	jurisdictionShaped := a.jurisdictionAudience != "" &&
		slices.Contains([]string(claims.Audience), a.jurisdictionAudience) &&
		hasScope(claims.Scope, scopeOpenID)
	// Account access token (ADR 20260729 / ENT-1383): aud is the issuing
	// core's own host — the same value pinned as the issuer above, whether
	// that came from expectedIssuer or from the trustedIssuers dispatch — no
	// scope requirement. Dual-accepted alongside the jurisdiction shape.
	accountAccessShaped := issuer != "" &&
		slices.Contains([]string(claims.Audience), issuer)
	if !jurisdictionShaped && !accountAccessShaped {
		return nil, fmt.Errorf("auth: token aud %v matches neither the jurisdiction nor the account-access audience", claims.Audience)
	}

	rawSubject := claims.Subject
	if rawSubject == "" {
		return nil, errors.New("auth: missing sub claim")
	}
	// Both accepted shapes are minted for accounts (ADR 20260729) or, since
	// COR-1109, for an automation principal (entiredb's automation exchange,
	// whose sub is "automation:<id>") under this exact (aud=iss, no scope)
	// shape too. classifySubject parses sub into a discriminated Subject
	// rather than refusing anything that isn't account-shaped — authorization
	// for the resulting principal is SpiceDB's job downstream, keyed on
	// whichever subject this resolves to.
	subject, ok := classifySubject(rawSubject)
	if !ok {
		return nil, fmt.Errorf("auth: sub %q is not a recognized principal shape", rawSubject)
	}
	// home_jurisdiction rides on both accepted token shapes (entire-core
	// #2094, ADR 20260729), so /me reads it here instead of calling Core.
	return &Identity{
		Subject:          subject,
		Handle:           claims.Handle,
		HomeJurisdiction: claims.HomeJurisdiction,
		Provider:         claims.Provider,
		ProviderUserID:   claims.ProviderUserID,
	}, nil
}

